public static long sumOf(int[] values) {
    long total = 0;
    if (values == null) return 0;
    for (int value : values)
        total += value;
    return total;
}

public static double averageOf(double[] values) {
    if (values == null || values.length == 0) return 0.0;
    double total = 0.0;
    for (double value : values)
        total += value;
    return total / values.length;
}

public static int countNegative(int[] values) {
    if (values == null) return 0;
    int count = 0;
    int index = 0;
    while (index < values.length) {
        if (values[index] < 0) count++;
        index++;
    }
    return count;
}

public static int countInRange(double[] values, double lower, double upper) {
    if (values == null || lower > upper) return 0;
    int count = 0;
    for (int i = 0; i < values.length; i++) {
        if (values[i] >= lower && values[i] <= upper) count++;
    }
    return count;
}

public static long sumBeforeFirstNegative(int[] values) {
    if (values == null) return 0;
    long total = 0;
    for (int value : values) {
        if (value < 0) break;
        total += value;
    }
    return total;
}

public static int countZeros(double[] values) {
