public static long sumMatrix(int[][] values) {
    if (values == null) return 0;
    long total = 0;
    for (int row = 0; row < values.length; row++) {
        if (values[row] != null) {
            for (int column = 0; column < values[row].length; column++) {
                total += values[row][column];
            }
        }
    }
    return total;
}

public static double sumPositive(double[] values) {
    double total = 0.0;
    if (values == null) return total;
    for (int i = 0; i < values.length; i++) {
        if (values[i] > 0.0) {
            total += values[i];
        }
    }
    return total;
}

public static int countEven(int[] values) {
    if (values == null || values.length == 0) return 0;
    int count = 0;
    int index = 0;
    while (index < values.length) {
        if (values[index] % 2 == 0) {
            count++;
        }
        index++;
    }
    return count;
}

public static double averagePositive(double[] values) {
    double total = 0.0;
    int count = 0;
    if (values == null) return 0.0;
    for (int i = 0; i < values.length; i++) {
        if (values[i] > 0.0) {
            total += values[i];
            count++;
        }
    }
    if (count == 0) return 0.0;
    return total / count;
}

public static int[] cumulativeSums(int[] values) {
    if (values == null) return new int[0];
    int[] totals = new int[values.length];
    int runningTotal = 0;
    for (int i = 0; i < values.length; i++) {
        runningTotal += values[i];
        totals[i] = runningTotal;
    }
    return totals;
}

