public static int countRowDivisibleValues(int[][] values) {
    if (values == null) return 0;
    int count = 0;
    for (int row = 0; row < values.length; row++) {
        if (values[row] != null) {
            int divisor = row + 1;
            for (int col = 0; col < values[row].length; col++) {
                if (values[row][col] % divisor == 0)
                    count++;
            }
        }
    }
    return count;
}

public static int countAtOrBelowPreviousAverage(int[] values) {
    if (values == null) return 0;
    long sum = values.length == 0 ? 0 : values[0];
    int count = 0;
    for (int i = 1; i < values.length; i++) {
        double previousAverage = sum / (double) i;
        if (values[i] < previousAverage)
            count++;
        else if (values[i] == previousAverage)
            count++;
        sum += values[i];
    }
    return count;
}

