public static int countPrimeValues(int[] values) {
    if (values == null) return 0;
    int count = 0;
    for (int value : values) {
        if (value < 2) continue;
        boolean prime = true;
        int divisor = 2;
        while (divisor <= value / divisor) {
            if (value % divisor == 0) { prime = false; break; }
            divisor++;
        }
        if (prime) count++;
    }
    return count;
}

code_b:
public static int countPrimeValues(int[] values) {
    if (values == null || values.length == 0) {
        return 0;
    }
    int count = 0;
    for (int i = 0; i < values.length; i++) {
        int value = values[i];
        if (value >= 2) {
            boolean isPrime = true;
            for (int divisor = 2; divisor <= value / divisor; divisor++) {
                if (value % divisor == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                count++;
            }
        }
    }
    return count;
}

