public static double averageAbsoluteDeviation(int[] values) {
    if (values == null || values.length == 0) return 0.0;
    double total = 0;
    for (int value : values) total += value;
    double mean = total / values.length;
    double deviations = 0;
    for (int value : values)
        deviations += Math.abs(value - mean);
    return deviations / values.length;
}

code_b:
