        return 0.0;
    }
    long sum = 0;
    for (int i = 0; i < values.length; i++) {
        sum += values[i];
    }
    double mean = (double) sum / values.length;
    double totalDeviation = 0.0;
    for (int i = 0; i < values.length; i++) {
        totalDeviation += Math.abs((double) values[i] - mean);
    }
    return totalDeviation / values.length;
}

