public static int countDistinctValues(int[] values) {
    if (values == null) return 0;
    int distinctCount = 0;
    for (int i = 0; i < values.length; i++) {
        boolean seenEarlier = false;
        for (int j = 0; j < i; j++) {
            if (values[i] == values[j]) { seenEarlier = true; break; }
        }
        if (!seenEarlier) distinctCount++;
    }
    return distinctCount;
}

