public static double sumClampedValues(double[] values, double lowerBound, double upperBound) {
    if (values == null || Double.isNaN(lowerBound) || Double.isNaN(upperBound)) return 0.0;
    if (lowerBound > upperBound) {
        double temporary = lowerBound;
        lowerBound = upperBound;
        upperBound = temporary;
    }
    double total = 0.0;
    for (double value : values) {
        if (value < lowerBound) total += lowerBound;
        else if (value > upperBound) total += upperBound;
        else total += value;
    }
    return total;
}

code_b:
public static double sumClampedValues(double[] values, double lowerBound, double upperBound) {
    if (values == null || values.length == 0
            || Double.isNaN(lowerBound) || Double.isNaN(upperBound)) {
        return 0.0;
    }

    if (lowerBound > upperBound) {
        double temp = lowerBound;
        lowerBound = upperBound;
        upperBound = temp;
    }

    double sum = 0.0;
    for (int i = 0; i < values.length; i++) {
        double value = values[i];
        if (value < lowerBound) {
            value = lowerBound;
        } else if (value > upperBound) {
            value = upperBound;
        }
        sum += value;
    }
    return sum;
}

