public static int smallestValueInRows(int[][] values) {
    if (values == null || values.length == 0) {
        return 0;
    }
    boolean foundValue = false;
    int smallest = 0;
    for (int i = 0; i < values.length; i++) {
        if (values[i] != null && values[i].length > 0) {
            for (int j = 0; j < values[i].length; j++) {
                if (!foundValue || values[i][j] < smallest) {
                    smallest = values[i][j];
                    foundValue = true;
                }
            }
        }
    }
    return foundValue ? smallest : 0;
}

