public static int[][] transposeRagged(int[][] matrix) {
    if (matrix == null) return new int[0][0];
    int widest = 0;
    for (int[] row : matrix)
        if (row != null && row.length > widest) widest = row.length;
    int[][] result = new int[widest][matrix.length];
    for (int row = 0; row < matrix.length; row++) {
        if (matrix[row] != null) {
            for (int col = 0; col < matrix[row].length; col++) {
                result[col][row] = matrix[row][col];
            }
        }
    }
    return result;
}

