public static long countPairsOfPerfectSquares(int[] values) {
    if (values == null) return 0;
    long count = 0;
    for (int i = 0; i < values.length; i++) {
        for (int j = i + 1; j < values.length; j++) {
            if (values[i] < 0 || values[j] < 0) continue;
            long rootI = 0;
            while (true) { if (rootI * rootI >= values[i]) break; rootI++; }
            long rootJ = 0;
            while (true) { if (rootJ * rootJ >= values[j]) break; rootJ++; }
            if (rootI * rootI == values[i] && rootJ * rootJ == values[j]) count++;
        }
    }
    return count;
}

