        return 0;
    }
    long squareCount = 0;
    for (int i = 0; i < values.length; i++) {
        if (values[i] >= 0) {
            long root = (long) Math.sqrt(values[i]);
            if (root * root == values[i]) {
                squareCount++;
            }
        }
    }
    return squareCount * (squareCount - 1) / 2;
}

