public static String classifyArraySum(int[] values) {
    if (values == null || values.length == 0) return "empty";
    long total = 0;
    for (int value : values) total += value;
    if (total <= 0) return "nonpositive";
    else if (total <= 100) return "small";
    else if (total <= 1000) return "medium";
    else return "large";
}

public static String classifyArrayRange(int[] values) {
    if (values == null || values.length == 0) return "empty";
    long minimum = values[0], maximum = values[0];
    int index = 1;
    while (index < values.length) {
        if (values[index] < minimum) minimum = values[index];
        if (values[index] > maximum) maximum = values[index];
        if (maximum - minimum > 1000) break;
        index++;
    }
    long range = maximum - minimum;
    if (range <= 10) return "narrow";
    else if (range <= 100) return "moderate";
    else if (range <= 1000) return "wide";
    else return "very wide";
}

public static String classifyUppercaseShare(char[] characters) {
    if (characters == null || characters.length == 0) return "empty";
    int letters = 0, uppercase = 0, index = 0;
    while (index < characters.length) {
        char character = characters[index];
        if ((character >= 'A' && character <= 'Z') || (character >= 'a' && character <= 'z')) {
            letters++;
            if (character >= 'A' && character <= 'Z') uppercase++;
        }
        index++;
    }
    if (letters == 0) return "no letters";
    double share = (double) uppercase / letters;
    if (share <= 0.25) return "low";
    else if (share <= 0.75) return "mixed";
    else return "mostly uppercase";
}

public static String classifyMatrixTotal(int[][] matrix) {
