    for (int[] row : matrix) {
        if (row == null) continue;
        for (int value : row) {
            total += value;
            foundValue = true;
        }
    }
    if (!foundValue) return "empty";
    if (total <= 0) return "nonpositive";
    else if (total <= 100) return "small";
    else if (total <= 1000) return "medium";
    else return "large";
}

public static String classifyListSpread(java.util.List<Integer> values) {
    if (values == null || values.isEmpty()) return "empty";
    Integer minimum = null, maximum = null;
    for (Integer value : values) {
        if (value == null) continue;
        if (minimum == null || value < minimum) minimum = value;
        if (maximum == null || value > maximum) maximum = value;
    }
    if (minimum == null) return "empty";
    long spread = (long) maximum - minimum;
    if (spread <= 10) return "compact";
    else if (spread <= 100) return "moderate";
    else return "broad";
}

