public static double power(double base, int exponent) {
    if (base == 0.0 && exponent < 0) return Double.NaN;
    long remaining = exponent;
    if (remaining < 0) remaining = -remaining;
    double result = 1.0;
    while (remaining > 0) {
        result *= base;
        remaining--;
    }
    if (exponent < 0) result = 1.0 / result;
    return result;
}

