    if (base == 0.0 && exponent < 0) {
        return Double.NaN;
    }

    long count = exponent;
    double factor = base;
    if (count < 0) {
        count = -count;
        factor = 1.0 / base;
    }

    double result = 1.0;
    while (count > 0) {
        result *= factor;
        count--;
    }
    return result;
}

