public static int largestDigit(long value) {
    int largest = 0;
    do {
        int digit = (int) (value % 10);
        if (digit < 0) digit = -digit;
        if (digit > largest) largest = digit;
        value /= 10;
    } while (value != 0);
    return largest;
}

public static int countCharacterRuns(String text) {
    if (text == null || text.isEmpty()) return 0;
    int runs = 0;
    char previous = '\0';
    boolean hasPrevious = false;
    for (char current : text.toCharArray()) {
        if (!hasPrevious || current != previous) runs++;
        previous = current;
        hasPrevious = true;
    }
    return runs;
}

public static boolean isPalindromeNumber(int value) {
    if (value < 0) return false;
    int original = value;
    long reversed = 0;
    while (value > 0) {
        reversed = reversed * 10 + value % 10;
        value /= 10;
    }
    return reversed == original;
}

public static boolean isArmstrongNumber(int value) {
    if (value < 0) return false;
    int digitCount = 0;
    int remaining = value;
    do {
        digitCount++;
        remaining /= 10;
    } while (remaining != 0);
    long sum = 0;
    remaining = value;
    while (remaining > 0) {
        int digit = remaining % 10;
        long digitPower = 1;
        for (int i = 0; i < digitCount; i++) digitPower *= digit;
        sum += digitPower;
        remaining /= 10;
    }
    return sum == value;
}

public static int countDivisors(int value) {
    if (value <= 0) return 0;
    int count = 0;
    for (int divisor = 1; divisor <= value / divisor; divisor++) {
        if (value % divisor == 0) {
            count++;
            if (divisor != value / divisor) count++;
        }
    }
    return count;
}

public static boolean isPerfectSquare(int value) {
    if (value < 0) return false;
    int low = 0;
    int high = Math.min(value, 46340);
    while (low <= high) {
        int middle = low + (high - low) / 2;
        long square = (long) middle * middle;
        if (square == value) return true;
        else if (square < value) low = middle + 1;
        else high = middle - 1;
    }
    return false;
}

public static int countPowersOfBaseAtMost(int limit, int base) {
    if (limit < 1 || base < 2) return 0;
    int count = 0;
    int power = 1;
    while (power <= limit) {
        count++;
        if (power > limit / base) break;
        power *= base;
    }
    return count;
}

public static int sumOfSquaredDigits(int number) {
    long remaining = Math.abs((long) number);
    int sum = 0;
    while (remaining > 0) {
        int digit = (int) (remaining % 10);
        sum += digit * digit;
        remaining /= 10;
    }
    return sum;
}

public static long reverseDigits(int number) {
    long remaining = Math.abs((long) number);
    long reversed = 0;
    for (; remaining > 0; remaining /= 10)
        reversed = reversed * 10 + remaining % 10;
    if (number < 0) reversed = -reversed;
    return reversed;
}

public static boolean isPowerOfBase(int number, int base) {
    if (number <= 0 || base < 2) return false;
    while (number % base == 0) {
        number /= base;
    }
    return number == 1;
}

public static long leastCommonMultiple(int a, int b) {
    long x = Math.abs((long) a);
    long y = Math.abs((long) b);
    if (x == 0 || y == 0) return 0;
    long first = x;
    long second = y;
    while (second != 0) {
        long remainder = first % second;
        first = second;
        second = remainder;
    }
    return x / first * y;
}

