public static int countOddCollatzStepsWithin(int start, int maxSteps) {
    if (start <= 0 || maxSteps <= 0) return 0;
    long value = start;
    int oddSteps = 0;
    for (int step = 0; step < maxSteps && value != 1; step++) {
        if (value % 2 == 0) value /= 2;
        else {
            if (value > (Long.MAX_VALUE - 1) / 3) break;
            oddSteps++;
            value = 3 * value + 1;
        }
    }
    return oddSteps;
}

