public static long countPairsWithEqualDigitSum(int[] values) {
    if (values == null || values.length < 2) return 0;
    long pairs = 0;
    for (int i = 0; i < values.length; i++) {
        long first = Math.abs((long) values[i]);
        int firstSum = 0;
        while (first > 0) { firstSum += first % 10; first /= 10; }
        for (int j = i + 1; j < values.length; j++) {
            long second = Math.abs((long) values[j]);
            int secondSum = 0;
            while (second > 0) { secondSum += second % 10; second /= 10; }
            if (firstSum == secondSum) pairs++;
        }
    }
    return pairs;
}

public static int countValuesWithSameFirstAndLastDigit(int[] values) {
    if (values == null) return 0;
    int count = 0;
    for (int value : values) {
        long magnitude = Math.abs((long) value);
        int lastDigit = (int) (magnitude % 10);
        while (magnitude >= 10) magnitude /= 10;
        if (value == 0) count++;
        else if ((int) magnitude == lastDigit) count++;
    }
    return count;
}

