        return 0;
    }
    int count = 0;
    for (int i = 0; i < firstMonths.length; i++) {
        int firstMonth = firstMonths[i];
        if (firstMonth < 1 || firstMonth > 12) {
            continue;
        }
        int firstQuarter = (firstMonth - 1) / 3;
        for (int j = 0; j < secondMonths.length; j++) {
            int secondMonth = secondMonths[j];
            if (secondMonth >= 1 && secondMonth <= 12
                    && firstQuarter == (secondMonth - 1) / 3) {
                count++;
            }
        }
    }
    return count;
}

