public static int[] rotateLeftByDistance(int[] values, int distance) {
    if (values == null || values.length < 2) return values;
    int shifts = distance % values.length;
    if (shifts < 0) shifts += values.length;
    while (shifts > 0) {
        int first = values[0];
        for (int i = 0; i < values.length - 1; i++)
            values[i] = values[i + 1];
        values[values.length - 1] = first;
        shifts--;
    }
    return values;
}

code_b:
public static int[] rotateLeftByDistance(int[] values, int distance) {
    if (values == null || values.length == 0) {
        return values;
    }

    int length = values.length;
    int shift = distance % length;
    if (shift < 0) {
        shift += length;
    }

    int[] rotated = new int[length];
    for (int i = 0; i < length; i++) {
        int sourceIndex;
        if (i >= length - shift) {
            sourceIndex = i - (length - shift);
        } else {
            sourceIndex = i + shift;
        }
        rotated[i] = values[sourceIndex];
    }
    System.arraycopy(rotated, 0, values, 0, length);
    return values;
}

