    if (values.length == 1) {
        values[0] = 0;
        return;
    }
    int previous = values[0];
    int current = values[1];
    values[0] = 0;
    for (int i = 1; i < values.length - 1; i++) {
        int next = values[i + 1];
        values[i] = current > previous && current > next ? 1 : 0;
        previous = current;
        current = next;
    }
    values[values.length - 1] = 0;
}

