public static int[] reverseNegativeRunsInPlace(int[] values) {
    if (values == null) return null;
    int start = 0;
    while (start < values.length) {
        if (values[start] >= 0) {
            start++;
            continue;
        }
        int end = start;
        while (end < values.length) {
            if (values[end] >= 0) break;
            end++;
        }
        int left = start;
        int right = end - 1;
        while (left < right) {
            int temp = values[left];
            values[left] = values[right];
            values[right] = temp;
            left++;
            right--;
        }
        start = end;
    }
    return values;
}

