        int previousCase = 0, letters = 0;
        boolean alternating = true;
        for (int i = 0; i < word.length(); i++) {
            char ch = word.charAt(i);
            int currentCase;
            if (ch >= 'A' && ch <= 'Z') currentCase = 1;
            else if (ch >= 'a' && ch <= 'z') currentCase = -1;
            else continue;
            if (previousCase != 0 && currentCase == previousCase) { alternating = false; break; }
            previousCase = currentCase;
            letters++;
        }
        if (alternating && letters >= 2) count++;
    }
    return count;
}

