public static double discountedMatrixTotal(int[][] prices, double discountPercent) {
    if (prices == null || prices.length == 0) return 0.0;
    if (Double.isNaN(discountPercent)) discountPercent = 0.0;
    else if (discountPercent < 0.0) discountPercent = 0.0;
    else if (discountPercent > 100.0) discountPercent = 100.0;
    double multiplier = 1.0 - discountPercent / 100.0;
    double total = 0.0;
    for (int row = 0; row < prices.length; row++) {
        if (prices[row] == null) break;
        if (prices[row].length > 0 && row >= 0) {
            for (int column = 0; column < prices[row].length; column++)
                total += prices[row][column] * multiplier;
        }
    }
    return total;
}

