    } else if (discountPercent < 0.0) {
        discountPercent = 0.0;
    } else if (discountPercent > 100.0) {
        discountPercent = 100.0;
    }
    double total = 0.0;
    for (int i = 0; i < prices.length; i++) {
        if (prices[i] == null) {
            break;
        }
        for (int price : prices[i]) {
            total += price;
        }
    }
    return total * (1.0 - discountPercent / 100.0);
}

