        if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) {
            letterCount++;
            if (ch >= 'A' && ch <= 'Z') {
                uppercaseCount++;
            }
        }
    }
    if (letterCount == 0) {
        return 0.0;
    }
    return 100.0 * uppercaseCount / letterCount;
}

