public static int findRepeatedBlockStart(int[] values, int blockLength) {
    if (values == null || blockLength <= 0 || blockLength > values.length / 2) return -1;
    for (int start = 0; start <= values.length - 2 * blockLength; start++) {
        boolean equal = true;
        for (int offset = 0; offset < blockLength; offset++) {
            if (values[start + offset] != values[start + blockLength + offset]) {
                equal = false;
                break;
