    long total = 0;
    for (int count : counts) {
        if (count < 0) return new int[0];
        total += count;
        if (total > Integer.MAX_VALUE) return new int[0];
    }
    int[] expanded = new int[(int) total];
    int position = 0;
    for (int i = 0; i < values.length; i++)
        for (int j = 0; j < counts[i]; j++)
            expanded[position++] = values[i];
    return expanded;
}

