    if (text == null) return true;
    int left = 0;
    int right = text.length() - 1;
    while (left < right && text.charAt(left) == text.charAt(right)) {
        left++;
        right--;
    }
    if (left >= right) return true;
    int i = left + 1;
    int j = right;
    boolean canSkipLeft = true;
    while (i < j && canSkipLeft) {
        if (text.charAt(i) == text.charAt(j)) { i++; j--; }
        else canSkipLeft = false;
    }
    i = left;
    j = right - 1;
    boolean canSkipRight = true;
    while (i < j && canSkipRight) {
        if (text.charAt(i) == text.charAt(j)) { i++; j--; }
        else canSkipRight = false;
    }
    return canSkipLeft || canSkipRight;
}

