public static int longestEqualListRun(List<Integer> values) {
    if (values == null) return 0;
    int best = 0;
    int i = 0;
    while (i < values.size()) {
        Integer current = values.get(i);
        if (current == null) { i++; continue; }
        int run = 1;
        while (i + run < values.size()) {
            Integer next = values.get(i + run);
            if (next == null || !current.equals(next)) break;
            run++;
        }
        if (run > best) best = run;
        i += run;
    }
    return best;
}

