public static int longestRepeatedLetterRun(String text) {
    if (text == null || text.isEmpty()) return 0;
    int longest = 0;
    int current = 0;
    int i = 0;
    while (i < text.length()) {
        char letter = text.charAt(i);
        if (Character.isLetter(letter) && i > 0
                && Character.isLetter(text.charAt(i - 1))
                && Character.toLowerCase(letter) == Character.toLowerCase(text.charAt(i - 1)))
            current++;
        else if (Character.isLetter(letter)) current = 1;
        else current = 0;
        if (current > longest) longest = current;
        i++;
    }
    return longest;
}

