public static int countCharacterRuns(String text) {
    if (text == null || text.length() == 0) return 0;
    int runs = 1;
    for (int i = 1; i < text.length(); i++) {
        if (text.charAt(i) != text.charAt(i - 1)) runs++;
    }
    return runs;
}

