public static int countUppercaseStartingWords(String text) {
    if (text == null || text.length() == 0) return 0;
    int count = 0;
    boolean atWordStart = true;
    for (int i = 0; i < text.length(); i++) {
        char c = text.charAt(i);
        if (c == ' ') atWordStart = true;
        else if (atWordStart) {
            if (c >= 'A' && c <= 'Z') count++;
            atWordStart = false;
        }
    }
    return count;
}

