    int start = 0;
    for (int i = 0; i <= text.length(); i++) {
        if (i == text.length() || text.charAt(i) == ' ') {
            if (start < i) {
                char first = text.charAt(start);
                if (first >= 'A' && first <= 'Z') {
                    count++;
                }
            }
            start = i + 1;
        }
    }
    return count;
}

