public static int countWordsEndingWithPunctuation(String text) {
    if (text == null || text.length() == 0) return 0;
    int count = 0;
    boolean inWord = false;
    char last = ' ';
    for (int i = 0; i < text.length(); i++) {
        char c = text.charAt(i);
        if (c == ' ') {
            if (inWord && (last == '!' || last == '?')) count++;
            inWord = false;
        } else {
            inWord = true;
            last = c;
        }
    }
    if (inWord && (last == '!' || last == '?')) count++;
    return count;
}

