public static int countRowsWithExactlyOneZero(int[][] values) {
    if (values == null || values.length == 0) return 0;
    int matchingRows = 0;
    for (int[] row : values) {
        if (row == null) continue;
        int zeroCount = 0;
        for (int value : row) {
            if (value == 0) zeroCount++;
        }
        if (zeroCount == 1) matchingRows++;
    }
    return matchingRows;
}

