public static int indexOfRowWithSmallestTotal(int[][] values) {
    if (values == null || values.length == 0) return -1;
    int smallestIndex = 0;
    long smallestTotal = 0;
    for (int i = 0; i < values.length; i++) {
        long total = 0;
        if (values[i] != null) {
            for (int value : values[i]) total += value;
        }
        if (i == 0 || total < smallestTotal) {
            smallestTotal = total;
            smallestIndex = i;
        }
    }
    return smallestIndex;
}

